#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
    requires
        // Needed to safely allocate a Vec of length a.len() + b.len().
        a.len() + b.len() <= usize::MAX,
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut res: Vec<i32> = Vec::new();
    res.reserve(a.len() + b.len());

    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
        decreases a.len() - i
    {
        res.push(a[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            res@.len() == a@.len() + j as int,
            // First part already matches `a`.
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            // Appended part so far matches prefix of `b`.
            forall|k: int| 0 <= k < j as int ==> res@[a@.len() + k] == b@[k],
        decreases b.len() - j
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!